window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"fissuur":{"title":"Fissuur","short":"Pijnlijke, spleetvormige scheur in de huid, vaak op handen of hielen (kloof/rhagade).","definition":"<p>Een <b>fissuur</b> (rhagade, kloof) is een smalle, spleetvormige scheur in de huid die tot in de dermis kan reiken.</p><p>Ze ontstaat vooral in droge, verdikte huid op belaste plaatsen zoals vingers, handen en hielen, en kan pijnlijk zijn.</p>","image_url":"","wiki_title":"Fissure","match":"fissuur|rhagade|rhagaden|kloof"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"metoprolol":{"title":"Metoprolol","short":"Metoprolol is een cardioselectieve bètablokker (β1) die hartfrequentie en contractiekracht verlaagt; gebruikt bij hypertensie, angina pectoris en hartfalen.","definition":"<p><strong>Metoprolol</strong> is een <em>β1-selectieve</em> bètablokker. Door blokkade van β1-receptoren in het hart dalen hartfrequentie, contractiliteit en geleidingssnelheid in de AV-knoop; in de nier remt het de reninesecretie.</p><p>Indicaties: hypertensie, angina pectoris, na een myocardinfarct, hartfalen en ritmestoornissen (frequentiecontrole). Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten. Bij hoge doses verdwijnt de selectiviteit en kan bronchoconstrictie optreden.</p>","image_url":"","wiki_title":"Metoprolol","match":"metoprolol","option_only":true},"bisoprolol":{"title":"Bisoprolol","short":"Bisoprolol is een sterk β1-selectieve bètablokker, gebruikt bij hypertensie, angina pectoris en hartfalen.","definition":"<p><strong>Bisoprolol</strong> is een <em>cardioselectieve</em> bètablokker met een hoge affiniteit voor β1-receptoren in het hart. Het verlaagt hartfrequentie, contractiekracht en zuurstofverbruik van het myocard.</p><p>Het wordt eenmaal daags gegeven bij hypertensie, stabiele angina pectoris, ritmestoornissen en hartfalen met verminderde ejectiefractie. Bijwerkingen zijn bradycardie, vermoeidheid en koude handen en voeten.</p>","image_url":"","wiki_title":"Bisoprolol","match":"bisoprolol","option_only":true},"hydrochloorthiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloorthiazide|hctz|thiazide|thiazidediureticum|thiazide diureticum|hydrochloortiazide","option_only":true},"acetylsalicylzuur":{"title":"Acetylsalicylzuur","short":"Acetylsalicylzuur (aspirine) remt onomkeerbaar het enzym cyclo-oxygenase; in lage dosis remt het de bloedplaatjesaggregatie.","definition":"<p><strong>Acetylsalicylzuur</strong> acetyleert en remt <em>onomkeerbaar</em> het enzym cyclo-oxygenase (COX-1 en COX-2). Daardoor worden minder prostaglandinen en tromboxaan A<sub>2</sub> gevormd.</p><p>In lage dosis (80–100 mg) remt het via tromboxaan de bloedplaatjesaggregatie voor de hele levensduur van het plaatje (±7–10 dagen); dit wordt gebruikt ter preventie van hart- en vaatziekten. In hoge dosis werkt het pijnstillend, koortsverlagend en ontstekingsremmend. Bijwerkingen: maagulcera, bloedingen en bij kinderen het syndroom van Reye.</p>","image_url":"","wiki_title":"Aspirin","match":"acetylsalicylzuur|aspirine|ascal|asa|carbasalaatcalcium","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"metformine":{"title":"Metformine","short":"Metformine is het eerstekeusmiddel bij diabetes mellitus type 2; het remt vooral de glucoseproductie door de lever.","definition":"<p><strong>Metformine</strong> is een biguanide dat de <em>gluconeogenese in de lever</em> remt en de insulinegevoeligheid van spier verbetert. Het stimuleert de insulineafgifte niet en geeft daarom op zichzelf geen hypoglykemie.</p><p>Het is eerste keus bij diabetes type 2 en is gewichtsneutraal. Bijwerkingen zijn vooral maag-darmklachten; zeldzaam is lactaatacidose (risico bij ernstige nierfunctiestoornis). Langdurig gebruik kan vitamine B12-tekort geven.</p>","image_url":"","wiki_title":"Metformin","match":"metformine|metformin","option_only":true},"foliumzuur":{"title":"Foliumzuur","short":"Foliumzuur (vitamine B11/B9) is nodig voor DNA-synthese; tekort geeft megaloblastaire anemie en verhoogt het risico op een neuralebuisdefect.","definition":"<p><strong>Foliumzuur</strong> (folaat) is als tetrahydrofolaat een drager van één-koolstofgroepen, nodig voor de synthese van purines en thymidine en dus voor <em>DNA-synthese</em> en celdeling.</p><p>Tekort geeft een <em>megaloblastaire (macrocytaire) anemie</em>. Een tekort rond de conceptie verhoogt het risico op neuralebuisdefecten (spina bifida); daarom wordt vrouwen met kinderwens aangeraden vanaf 4 weken voor de conceptie tot 10 weken zwangerschap foliumzuur te slikken.</p>","image_url":"","wiki_title":"Folate","match":"foliumzuur|folaat|vitamine b11|vitamine b9","option_only":true},"calcium/d3":{"title":"Calcium en vitamine D3","short":"Calcium met vitamine D3 wordt gegeven ter preventie en behandeling van osteoporose, vooral bij ouderen en bij gebruik van corticosteroïden of bisfosfonaten.","definition":"<p>Een combinatiepreparaat van <strong>calcium en vitamine D3</strong> (colecalciferol) ondersteunt de botmineralisatie. Vitamine D bevordert de calciumopname in de darm; calcium is de bouwstof van hydroxyapatiet in bot.</p><p>Het wordt voorgeschreven bij osteoporose (naast bisfosfonaten), bij ouderen met een laag vitamine D en bij langdurig corticosteroïdgebruik. Bijwerkingen zijn obstipatie en zelden hypercalciëmie.</p>","image_url":"","wiki_title":"","match":"calcium/d3|calcium/vitamine d|calcium en vitamine d|calcium/vitamine d3","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"respiratoire alkalose":{"title":"Respiratoire alkalose","short":"Bij een respiratoire alkalose stijgt de pH doordat door hyperventilatie te veel CO₂ wordt uitgeademd (lage pCO₂).","definition":"<p>Bij een <strong>respiratoire alkalose</strong> is de pCO<sub>2</sub> verlaagd door <em>hyperventilatie</em>, waardoor de pH stijgt. Oorzaken: angst/paniek, pijn, hypoxie (hoogte, longembolie, pneumonie), koorts, zwangerschap, salicylaatintoxicatie en levercirrose.</p><p>De nier compenseert (langzaam, over dagen) door minder bicarbonaat terug te resorberen. Acute klachten: tintelingen rond de mond en in de vingers, duizeligheid en soms tetanie, door daling van het geïoniseerde calcium.</p>","image_url":"","wiki_title":"Respiratory alkalosis","match":"respiratoire alkalose","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"epilepsie":{"title":"Epilepsie","short":"Epilepsie is een hersenaandoening met herhaalde, niet-uitgelokte epileptische aanvallen door abnormale, synchrone ontladingen van neuronen.","definition":"<p>Bij <strong>epilepsie</strong> heeft iemand de neiging tot herhaalde epileptische aanvallen. Een aanval ontstaat door een plotselinge, overmatige en gesynchroniseerde ontlading van groepen neuronen.</p><p>Aanvallen kunnen focaal beginnen (in één hersengebied; met of zonder bewustzijnsdaling) of gegeneraliseerd (beide hemisferen; bijv. tonisch-klonische aanvallen of absences). Oorzaken: genetisch, structureel (litteken, tumor, ontwikkelingsstoornis), infectieus, metabool of onbekend. Diagnostiek met anamnese/heteroanamnese, EEG en MRI.</p>","image_url":"","wiki_title":"Epilepsy","match":"epilepsie","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"tia":{"title":"Transient ischaemic attack (TIA)","short":"Een TIA is een kortdurende uitval van een hersenfunctie door tijdelijke ischemie, zonder blijvend infarct; een belangrijk waarschuwingssignaal voor een herseninfarct.","definition":"<p>Bij een <strong>TIA</strong> (transient ischaemic attack) ontstaan plotseling focale neurologische klachten (bijv. halfzijdige verlamming, afasie, monoculaire blindheid) die meestal binnen enkele minuten tot een uur volledig verdwijnen, zonder infarct op beeldvorming.</p><p>De oorzaak is meestal een embolie (vanuit de carotis of het hart, bijv. bij boezemfibrilleren) of een kleine-vatenafwijking. Na een TIA is het risico op een herseninfarct in de eerste dagen sterk verhoogd; snelle analyse en secundaire preventie (antistolling of plaatjesremmers, statine, bloeddruk) zijn nodig.</p>","image_url":"","wiki_title":"Transient ischemic attack","match":"tia|transient ischaemic attack|transient ischemic attack","option_only":true},"vitamine b12":{"title":"Vitamine B12 (cobalamine)","short":"Vitamine B12 is nodig voor DNA-synthese en de myelinevorming; opname vereist intrinsieke factor uit de maag en een gezond terminaal ileum.","definition":"<p><strong>Vitamine B12</strong> komt alleen uit dierlijke producten. In de maag bindt het aan intrinsieke factor (van pariëtale cellen); het complex wordt in het terminale ileum opgenomen. B12 is cofactor van methioninesynthase (koppeling met foliumzuur) en methylmalonyl-CoA-mutase. Tekort ontstaat door bijv. auto-immuungastritis (pernicieuze anemie), maag- of ileumresectie, metformine of veganisme, en geeft macrocytaire anemie en neurologische schade.</p>","image_url":"","wiki_title":"Vitamin B12","match":"vitamine b12|cobalamine|b12","option_only":true},"vitamine a":{"title":"Vitamine A (retinol)","short":"Vitamine A is een in vet oplosbare vitamine die nodig is voor het zien in het donker, de opbouw van epitheel en de afweer.","definition":"<p><strong>Vitamine A</strong> komt als retinol uit dierlijke producten en als bètacaroteen uit groenten. In de retina vormt retinal samen met opsine het lichtgevoelige rodopsine. Retinoïnezuur reguleert de groei en differentiatie van epitheel. Tekort geeft nachtblindheid, droge ogen (xeroftalmie) en meer infecties; overmaat is teratogeen en levertoxisch.</p>","image_url":"","wiki_title":"Vitamin A","match":"vitamine a|retinol|retinoïnezuur","option_only":true},"vitamine d":{"title":"Vitamine D","short":"Vitamine D bevordert de opname van calcium en fosfaat uit de darm en is nodig voor sterke botten.","definition":"<p><strong>Vitamine D</strong> wordt in de huid onder invloed van UVB-licht gemaakt of via de voeding opgenomen. De lever zet het om in 25-OH-vitamine D en de nier (onder invloed van PTH) in het actieve 1,25-(OH)₂-vitamine D (calcitriol). Calcitriol verhoogt de opname van calcium en fosfaat in de darm. Tekort geeft rachitis bij kinderen en osteomalacie bij volwassenen.</p>","image_url":"","wiki_title":"Vitamin D","match":"vitamine d|calcitriol|colecalciferol|vitamine d3","option_only":true},"ijzer":{"title":"IJzer","short":"IJzer is nodig voor hemoglobine, myoglobine en enzymen; het lichaam regelt de ijzervoorraad vooral via de opname in de darm.","definition":"<p><strong>IJzer</strong> wordt vooral in het duodenum opgenomen, als heemijzer of als Fe²⁺. In het bloed wordt het vervoerd door transferrine en opgeslagen als ferritine. Het hormoon hepcidine uit de lever remt de opname en afgifte. Het lichaam heeft geen actieve uitscheidingsroute, dus verlies gaat vooral via bloedverlies.</p>","image_url":"","wiki_title":"Iron in biology","match":"ijzer|fe|ijzersuppletie","option_only":true},"insuline":{"title":"Insuline","short":"Insuline is het hormoon uit de bètacellen van de pancreas dat de bloedglucose verlaagt en opbouwprocessen stimuleert.","definition":"<p><strong>Insuline</strong> wordt afgegeven als de glucose stijgt. Het bevordert de opname van glucose in spier en vet (via GLUT4), de opslag als glycogeen en vet, en de eiwitsynthese, en remt gluconeogenese, glycogenolyse en lipolyse. Het wordt gemaakt als proinsuline; de afsplitsing van C-peptide maakt het actief. Als geneesmiddel is het onmisbaar bij diabetes type 1.</p>","image_url":"","wiki_title":"Insulin","match":"insuline|insulin","option_only":true},"lisinopril":{"title":"Lisinopril","short":"Lisinopril is een ACE-remmer die de vorming van angiotensine II remt; gebruikt bij hypertensie en hartfalen.","definition":"<p><strong>Lisinopril</strong> remt het angiotensine-converterend enzym. Daardoor ontstaat minder angiotensine II (minder vasoconstrictie en aldosteron) en wordt minder bradykinine afgebroken. Het verlaagt de bloeddruk en beschermt hart en nieren. Bijwerkingen: prikkelhoest (bradykinine), hyperkaliëmie, stijging van creatinine en zelden angio-oedeem.</p>","image_url":"","wiki_title":"Lisinopril","match":"lisinopril","option_only":true},"enalapril":{"title":"Enalapril","short":"Enalapril is een ACE-remmer (prodrug) die wordt gebruikt bij hypertensie en hartfalen.","definition":"<p><strong>Enalapril</strong> wordt in de lever omgezet in het actieve enalaprilaat, dat het angiotensine-converterend enzym remt. Zo dalen angiotensine II en aldosteron. Bijwerkingen zijn droge hoest, hyperkaliëmie, nierfunctieverslechtering (vooral bij nierarteriestenose) en angio-oedeem; het is gecontra-indiceerd in de zwangerschap.</p>","image_url":"","wiki_title":"Enalapril","match":"enalapril","option_only":true},"ace remmer":{"title":"ACE-remmer","short":"ACE-remmers remmen de omzetting van angiotensine I naar angiotensine II; ze verlagen de bloeddruk en beschermen hart en nieren.","definition":"<p><strong>ACE-remmers</strong> (bijv. lisinopril, enalapril, perindopril) remmen het angiotensine-converterend enzym. Daardoor dalen vasoconstrictie en aldosteronafgifte, en stijgt bradykinine. Ze worden gebruikt bij hypertensie, hartfalen, na een myocardinfarct en bij diabetische nefropathie. Bijwerkingen: prikkelhoest, hyperkaliëmie, creatininestijging en angio-oedeem; niet geven in de zwangerschap.</p>","image_url":"","wiki_title":"ACE inhibitor","match":"ace remmer|ace-remmer|ace-remmers|ace remmers","option_only":true},"losartan":{"title":"Losartan","short":"Losartan is een angiotensine II-receptorblokker (ARB) bij hypertensie en hartfalen.","definition":"<p><strong>Losartan</strong> blokkeert de AT1-receptor, waardoor angiotensine II geen vasoconstrictie en aldosteronafgifte meer kan veroorzaken. Omdat het bradykinine niet beïnvloedt, geeft het minder vaak hoest dan ACE-remmers. Bijwerkingen zijn hyperkaliëmie en nierfunctieverslechtering; niet geven in de zwangerschap.</p>","image_url":"","wiki_title":"Losartan","match":"losartan","option_only":true},"nifedipine":{"title":"Nifedipine","short":"Nifedipine is een dihydropyridine-calciumantagonist die vooral de bloedvaten verwijdt.","definition":"<p><strong>Nifedipine</strong> blokkeert L-type calciumkanalen in vasculaire gladde spier, wat arteriële vaatverwijding geeft. Het heeft weinig effect op het hart. Het wordt gebruikt bij hypertensie, angina pectoris, het fenomeen van Raynaud en als weeënremmer. Bijwerkingen: enkeloedeem, hoofdpijn, flushing en reflextachycardie.</p>","image_url":"","wiki_title":"Nifedipine","match":"nifedipine","option_only":true},"simvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"simvastatine|statine|statines","option_only":true},"acenocoumarol":{"title":"Acenocoumarol","short":"Acenocoumarol is een kortwerkende cumarine (vitamine K-antagonist) voor antistolling, gedoseerd op geleide van de INR.","definition":"<p><strong>Acenocoumarol</strong> werkt net als fenprocoumon door remming van de vitamine K-cyclus, maar heeft een kortere halfwaardetijd. Het wordt gebruikt bij o.a. boezemfibrilleren, trombose en kunstkleppen. Controle via de INR is nodig; veel geneesmiddelen (zoals antibiotica) en wisselende vitamine K-inname beïnvloeden het effect.</p>","image_url":"","wiki_title":"Acenocoumarol","match":"acenocoumarol|sintrom","option_only":true},"neuritis vestibularis":{"title":"Neuritis vestibularis","short":"Neuritis vestibularis is een (vermoedelijk virale) ontsteking van de n. vestibularis met acute, dagenlange draaiduizeligheid zonder gehoorverlies.","definition":"<p>Bij <strong>neuritis vestibularis</strong> valt het evenwichtsorgaan aan één kant plotseling uit. Dat geeft heftige draaiduizeligheid, misselijkheid, braken en een horizontale nystagmus naar de gezonde kant, zonder gehoorverlies of andere neurologische uitval. De head-impulstest is afwijkend. Het herstel verloopt over dagen tot weken via centrale compensatie.</p>","image_url":"","wiki_title":"Vestibular neuritis","match":"neuritis vestibularis|neuronitis vestibularis","option_only":true},"neuropathie":{"title":"Neuropathie","short":"Neuropathie is een aandoening van perifere zenuwen, met gevoelsstoornissen, krachtsverlies en/of verlaagde reflexen.","definition":"<p>Een <strong>neuropathie</strong> kan één zenuw treffen (mononeuropathie, bijv. carpaletunnelsyndroom), meerdere zenuwen asymmetrisch (mononeuritis multiplex) of symmetrisch veel zenuwen tegelijk (polyneuropathie, typisch beginnend in de voeten). Oorzaken zijn o.a. diabetes, alcohol, vitamine B12-tekort, medicatie (chemotherapie), auto-immuniteit en erfelijke aandoeningen.</p>","image_url":"","wiki_title":"Peripheral neuropathy","match":"neuropathie|perifere neuropathie","option_only":true},"herseninfarct":{"title":"Herseninfarct","short":"Een herseninfarct ontstaat door afsluiting van een hersenarterie, waardoor hersenweefsel afsterft; het geeft plotselinge focale uitval.","definition":"<p>Een <strong>herseninfarct</strong> wordt veroorzaakt door trombose (bijv. bij atherosclerose of kleine-vatenziekte) of embolie (vaak uit het hart bij boezemfibrilleren of uit de carotis). Klachten ontstaan plotseling, afhankelijk van het vaatgebied: halfzijdige verlamming, gevoelsstoornis, afasie, gezichtsvelduitval. Acute behandeling binnen het tijdvenster: intraveneuze trombolyse en/of trombectomie.</p>","image_url":"","wiki_title":"Ischemic stroke","match":"herseninfarct|ischemisch cva|stroke (herseninfarct)|ischemisch herseninfarct","option_only":true},"antibiotica":{"title":"Antibiotica","short":"Antibiotica zijn middelen die bacteriën doden of hun groei remmen; ze werken niet tegen virussen.","definition":"<p><strong>Antibiotica</strong> grijpen aan op structuren die bacteriën wel en menselijke cellen niet (of anders) hebben: de celwand (bètalactams, vancomycine), het ribosoom (o.a. macroliden, tetracyclines, aminoglycosiden), DNA-synthese (chinolonen, metronidazol) of foliumzuursynthese (trimethoprim, sulfonamiden). Bacteriostatisch betekent groeiremmend, bactericide dodend. Onnodig gebruik bevordert resistentie.</p>","image_url":"","wiki_title":"Antibiotic","match":"antibiotica|antibioticum","option_only":true},"copd":{"title":"COPD","short":"COPD is een chronische longziekte met niet volledig omkeerbare luchtwegobstructie, meestal door roken.","definition":"<p>Bij <strong>COPD</strong> leiden chronische ontsteking van de kleine luchtwegen en afbraak van alveolewanden (emfyseem) tot een blijvende obstructie: FEV1/FVC &lt; 0,7 na bronchodilatatie. Klachten zijn kortademigheid bij inspanning, chronische hoest en sputum, met periodes van verergering (exacerbaties). Belangrijkste behandeling: stoppen met roken, luchtwegverwijders, beweegprogramma's en vaccinaties.</p>","image_url":"","wiki_title":"Chronic obstructive pulmonary disease","match":"copd|chronic obstructive pulmonary disease|chronisch obstructieve longziekte","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"nierinsufficiëntie|nierfalen|nierinsufficientie|chronische nierschade","option_only":true},"dehydratie":{"title":"Dehydratie","short":"Dehydratie is een tekort aan lichaamsvocht, door te weinig inname of te veel verlies (braken, diarree, zweten, polyurie).","definition":"<p>Bij <strong>dehydratie</strong> daalt het circulerend volume, met dorst, droge slijmvliezen, verminderde huidturgor, tachycardie, orthostatische hypotensie en weinig plassen. Kinderen en ouderen zijn extra kwetsbaar. Afhankelijk van verlies van water ten opzichte van zout kan de natriumconcentratie normaal, verhoogd of verlaagd zijn. Behandeling met orale rehydratie of infuus.</p>","image_url":"","wiki_title":"Dehydration","match":"dehydratie|uitdroging|ondervulling","option_only":true},"hypercalciëmie":{"title":"Hypercalciëmie","short":"Hypercalciëmie is een te hoog calcium in het bloed, meestal door primaire hyperparathyreoïdie of een maligniteit.","definition":"<p>Klachten van <strong>hypercalciëmie</strong> zijn samen te vatten als ‘stones, bones, groans and psychic moans’: nierstenen en polyurie, botpijn, obstipatie, misselijkheid en buikpijn, vermoeidheid en verwardheid; ook een verkort QT-interval. Bij maligniteit gaat het om PTHrP-productie, botmetastasen of (bij lymfomen) overmatig calcitriol. Behandeling: ruim vocht en bisfosfonaten.</p>","image_url":"","wiki_title":"Hypercalcaemia","match":"hypercalciëmie|hypercalciemie","option_only":true},"metabole acidose":{"title":"Metabole acidose","short":"Bij een metabole acidose is het bicarbonaat verlaagd en daalt de pH, door ophoping van zuren of verlies van bicarbonaat.","definition":"<p>Een <strong>metabole acidose</strong> wordt ingedeeld met de aniongap. Een <em>verhoogde</em> aniongap past bij ophoping van zuren: lactaat, ketonen (diabetische ketoacidose), nierfalen of intoxicaties (methanol, ethyleenglycol, salicylaten). Een <em>normale</em> aniongap past bij verlies van bicarbonaat via diarree of een renale tubulaire acidose. De ademhaling compenseert met diepe, snelle ademhaling (Kussmaul).</p>","image_url":"","wiki_title":"Metabolic acidosis","match":"metabole acidose","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"obstipatie":{"title":"Obstipatie","short":"Obstipatie is een te harde en/of te weinig frequente ontlasting, vaak met moeizaam persen.","definition":"<p>Van <strong>obstipatie</strong> spreekt men bij minder dan drie keer per week ontlasting, harde ontlasting, persen of een gevoel van onvolledige lediging. Oorzaken zijn o.a. weinig vezels en vocht, weinig beweging, medicatie (opioïden, ijzer, anticholinergica, calciumantagonisten), hypothyreoïdie, hypercalciëmie, neurologische ziekten en obstructie door een tumor. Behandeling met leefstijladviezen en laxantia zoals macrogol.</p>","image_url":"","wiki_title":"Constipation","match":"obstipatie|verstopping|constipatie","option_only":true},"omeprazol":{"title":"Omeprazol","short":"Omeprazol is een protonpompremmer die de maagzuurproductie sterk vermindert.","definition":"<p><strong>Omeprazol</strong> remt de H⁺/K⁺-ATPase van de pariëtale cellen onomkeerbaar. Het wordt gebruikt bij refluxziekte, ulcus pepticum, H. pylori-eradicatie en als maagbescherming bij NSAID-gebruik. Langdurig gebruik kan leiden tot o.a. hypomagnesiëmie, vitamine B12-tekort en een iets verhoogd risico op darminfecties; omeprazol remt CYP2C19.</p>","image_url":"","wiki_title":"Omeprazole","match":"omeprazol|protonpompremmer|ppi","option_only":true},"movicolon":{"title":"Macrogol (Movicolon)","short":"Movicolon is een osmotisch laxans op basis van macrogol dat water in de darm vasthoudt en de ontlasting zachter maakt.","definition":"<p><strong>Macrogol</strong> (polyethyleenglycol) wordt nauwelijks opgenomen en bindt water in het darmlumen, waardoor de ontlasting zachter en volumineuzer wordt. Het is een eerste keus laxans bij obstipatie, ook bij kinderen en bij opioïdgebruik. De elektrolyten in Movicolon voorkomen netto zoutverlies.</p>","image_url":"","wiki_title":"Polyethylene glycol","match":"movicolon|macrogol","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"fosamax":{"title":"Alendroninezuur (Fosamax)","short":"Fosamax (alendroninezuur) is een bisfosfonaat dat botafbraak door osteoclasten remt; gebruikt bij osteoporose.","definition":"<p><strong>Bisfosfonaten</strong> binden aan hydroxyapatiet en worden opgenomen door osteoclasten, die daardoor minder bot afbreken. Alendroninezuur wordt eenmaal per week ingenomen, nuchter met een vol glas water, waarna iemand 30 minuten rechtop moet blijven om slokdarmirritatie te voorkomen. Zeldzame bijwerkingen zijn osteonecrose van de kaak en atypische femurfracturen.</p>","image_url":"","wiki_title":"Alendronic acid","match":"fosamax|alendroninezuur|alendronaat|bisfosfonaat|bisfosfonaten","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"refractieafwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractieafwijking|refractiefout","option_only":true},"wmo":{"title":"Wet maatschappelijke ondersteuning (Wmo)","short":"De Wmo maakt gemeenten verantwoordelijk voor ondersteuning, zelfredzaamheid en participatie van hun inwoners.","definition":"<p>De <strong>Wet maatschappelijke ondersteuning</strong> regelt dat gemeenten zorgen voor ondersteuning van burgers die dat nodig hebben om zelfstandig te wonen en mee te doen, zoals huishoudelijke hulp, woningaanpassingen, begeleiding, mantelzorgondersteuning en maatschappelijke opvang.</p>","image_url":"","wiki_title":"","match":"wmo|wet maatschappelijke ondersteuning","option_only":true},"citalopram":{"title":"Citalopram","short":"Citalopram is een SSRI (selectieve serotonineheropnameremmer) die wordt gebruikt bij depressie en angststoornissen.","definition":"<p><strong>Citalopram</strong> remt de heropname van serotonine in de presynaptische zenuwcel. Het effect op de stemming begint na enkele weken. Bijwerkingen: misselijkheid, slaapproblemen, seksuele disfunctie, hyponatriëmie (vooral bij ouderen) en een dosisafhankelijke QT-verlenging. Combinatie met andere serotonerge middelen geeft risico op een serotoninesyndroom.</p>","image_url":"","wiki_title":"Citalopram","match":"citalopram|escitalopram","option_only":true},"sertraline":{"title":"Sertraline","short":"Sertraline is een SSRI die wordt gebruikt bij depressie, angststoornissen, OCS en PTSS.","definition":"<p><strong>Sertraline</strong> remt selectief de heropname van serotonine. Het heeft relatief weinig interacties en wordt ook in de zwangerschap en bij hartpatiënten veel gebruikt. Bijwerkingen zijn vooral maag-darmklachten, slapeloosheid, seksuele disfunctie en in het begin soms meer onrust.</p>","image_url":"","wiki_title":"Sertraline","match":"sertraline","option_only":true},"oxazepam":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"oxazepam|benzodiazepine|benzodiazepinen","option_only":true},"temazepam":{"title":"Temazepam","short":"Temazepam is een benzodiazepine met een middellange werkingsduur, vooral gebruikt als slaapmiddel.","definition":"<p><strong>Temazepam</strong> versterkt de remmende werking van GABA. Het wordt gebruikt bij kortdurende slapeloosheid. Bij langdurig gebruik ontstaan gewenning en afhankelijkheid; bij ouderen geeft het een verhoogd risico op vallen, sufheid overdag en verwardheid.</p>","image_url":"","wiki_title":"Temazepam","match":"temazepam","option_only":true},"morfine":{"title":"Morfine","short":"Morfine is een sterk werkend opioïd dat µ-opioïdreceptoren activeert; gebruikt bij ernstige pijn en kortademigheid in de palliatieve fase.","definition":"<p><strong>Morfine</strong> werkt pijnstillend via µ-receptoren in het centrale zenuwstelsel. Bijwerkingen zijn obstipatie (altijd een laxans erbij), misselijkheid, sufheid, ademhalingsdepressie, miosis en jeuk; bij langdurig gebruik ontstaan tolerantie en afhankelijkheid. De actieve metabolieten worden via de nier uitgescheiden en hopen op bij nierfalen. Antidotum: naloxon.</p>","image_url":"","wiki_title":"Morphine","match":"morfine|morphine","option_only":true},"oxycodon":{"title":"Oxycodon","short":"Oxycodon is een sterk werkend opioïd voor (matig) ernstige pijn.","definition":"<p><strong>Oxycodon</strong> is een µ-opioïdreceptoragonist met een vergelijkbaar effect en bijwerkingenprofiel als morfine (obstipatie, sufheid, ademhalingsdepressie). Het wordt via de lever (CYP3A4, CYP2D6) omgezet en is daarom een alternatief bij nierfunctiestoornissen. Er zijn snel- en langwerkende vormen; misbruik is een probleem.</p>","image_url":"","wiki_title":"Oxycodone","match":"oxycodon|oxycodone","option_only":true},"glimepiride":{"title":"Glimepiride","short":"Glimepiride is een sulfonylureumderivaat dat de bètacellen aanzet tot insulineafgifte; gebruikt bij diabetes type 2.","definition":"<p><strong>Sulfonylureumderivaten</strong> sluiten ATP-gevoelige kaliumkanalen in de bètacel, waardoor de cel depolariseert en insuline afgeeft, onafhankelijk van de glucosespiegel. Daardoor kunnen ze hypoglykemieën geven, vooral bij ouderen en verminderde nierfunctie. Andere bijwerking is gewichtstoename.</p>","image_url":"","wiki_title":"Glimepiride","match":"glimepiride|sulfonylureumderivaat|sulfonylureumderivaten","option_only":true},"beta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"beta-blokker|bètablokker|betablokker|bètablokkers|beta-blokkers","option_only":true},"lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lisdiureticum|lisdiuretica|furosemide|bumetanide","option_only":true},"resonium per os":{"title":"Natriumpolystyreensulfonaat (Resonium)","short":"Resonium is een kationenwisselaar die in de darm kalium bindt en zo de kaliumspiegel verlaagt.","definition":"<p><strong>Natriumpolystyreensulfonaat</strong> wisselt in de darm natrium uit tegen kalium, dat vervolgens met de ontlasting wordt uitgescheiden. Het werkt traag (uren) en is dus geschikt om het lichaam van kalium te ontdoen, niet om acuut gevaarlijke hyperkaliëmie snel te corrigeren. Bijwerkingen: obstipatie, natriumbelasting en zelden darmnecrose.</p>","image_url":"","wiki_title":"Sodium polystyrene sulfonate","match":"resonium per os|resonium|kayexalaat|polystyreensulfonaat","option_only":true},"calciumgluconaat intraveneus":{"title":"Calciumgluconaat intraveneus","short":"Intraveneus calciumgluconaat stabiliseert het hartmembraan bij ernstige hyperkaliëmie en corrigeert een symptomatische hypocalciëmie.","definition":"<p><strong>Calciumgluconaat</strong> verhoogt de drempelpotentiaal van hartspiercellen en vermindert zo binnen minuten het risico op ritmestoornissen bij hyperkaliëmie, zonder het kalium zelf te verlagen. Daarnaast is het de behandeling van symptomatische hypocalciëmie (tetanie) en wordt het gegeven bij magnesiumintoxicatie. Het moet langzaam worden toegediend.</p>","image_url":"","wiki_title":"Calcium gluconate","match":"calciumgluconaat intraveneus|calciumgluconaat|calcium intraveneus","option_only":true},"aldosteron-remmer":{"title":"Aldosteronantagonist","short":"Aldosteronantagonisten (spironolacton, eplerenon) blokkeren de mineralocorticoïdreceptor; ze zijn kaliumsparend en werken bij hartfalen en hyperaldosteronisme.","definition":"<p><strong>Spironolacton</strong> en <strong>eplerenon</strong> remmen het effect van aldosteron in de verzamelbuis, waardoor natrium wordt uitgescheiden en kalium wordt vastgehouden. Ze verlagen de sterfte bij hartfalen met verminderde ejectiefractie en worden gebruikt bij primair hyperaldosteronisme, ascites en therapieresistente hypertensie. Bijwerkingen: hyperkaliëmie en (vooral spironolacton) gynaecomastie.</p>","image_url":"","wiki_title":"Mineralocorticoid receptor antagonist","match":"aldosteron-remmer|aldosteronantagonist|spironolacton|eplerenon","option_only":true},"wet langdurige zorg":{"title":"Wet langdurige zorg (Wlz)","short":"De Wet langdurige zorg regelt zorg voor mensen die blijvend 24 uur per dag zorg in de nabijheid of toezicht nodig hebben.","definition":"<p>De <strong>Wlz</strong> is bedoeld voor bijvoorbeeld ouderen met vergevorderde dementie en mensen met een ernstige verstandelijke, lichamelijke of zintuiglijke beperking. Het CIZ stelt de indicatie vast; de zorg kan in een instelling of thuis worden geleverd. De uitvoering ligt bij zorgkantoren.</p>","image_url":"","wiki_title":"","match":"wet langdurige zorg|wlz","option_only":true},"retinopathie":{"title":"Retinopathie","short":"Retinopathie is een aandoening van het netvlies, meestal door schade aan de kleine bloedvaten, zoals bij diabetes of hypertensie.","definition":"<p>Belangrijke vormen van <strong>retinopathie</strong> zijn diabetische retinopathie (microaneurysmata, bloedingen, exsudaten en later nieuwvorming van vaten), hypertensieve retinopathie (vernauwde arteriolen, kruisingsfenomenen, bloedingen en bij maligne hypertensie papiloedeem) en prematurenretinopathie. Regelmatige oogcontrole bij diabetes voorkomt blindheid.</p>","image_url":"","wiki_title":"Retinopathy","match":"retinopathie","option_only":true},"maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"maculadegeneratie|leeftijdsgebonden maculadegeneratie|lmd|amd","option_only":true},"benigne paroxysmale positieveranderingsduizeligheid (bppd)":{"title":"BPPD","short":"BPPD is kortdurende draaiduizeligheid bij hoofdbewegingen, doordat losse otolieten in een halfcirkelvormig kanaal zijn terechtgekomen.","definition":"<p>Bij <strong>BPPD</strong> bewegen losgeraakte kalkkristallen bij een verandering van hoofdhouding (omdraaien in bed, opkijken) in meestal het achterste kanaal, wat seconden tot een minuut heftige draaiduizeligheid geeft. De Dix-Hallpike-test lokt een nystagmus uit. Behandeling met een repositiemanoeuvre (Epley).</p>","image_url":"","wiki_title":"Benign paroxysmal positional vertigo","match":"benigne paroxysmale positieveranderingsduizeligheid (bppd)|bppd|benigne paroxysmale positieduizeligheid","option_only":true},"thiazidediuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediuretica","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"thiazide diureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide diureticum","option_only":true},"hydrochloortiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloortiazide","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"tricyclisch antidepressivum":{"title":"Tricyclische antidepressiva","short":"Tricyclische antidepressiva remmen de heropname van noradrenaline en serotonine en hebben veel anticholinerge bijwerkingen.","definition":"<p><strong>TCA's</strong> (zoals amitriptyline, nortriptyline, clomipramine) worden gebruikt bij depressie en in lage dosis bij neuropathische pijn. Bijwerkingen: droge mond, obstipatie, urineretentie, sufheid, orthostatische hypotensie en gewichtstoename. Bij overdosering zijn ze gevaarlijk door natriumkanaalblokkade (breed QRS, aritmieën) en insulten.</p>","image_url":"","wiki_title":"Tricyclic antidepressant","match":"tricyclisch antidepressivum|tricyclische antidepressiva|tca|amitriptyline|nortriptyline","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"spitse t-toppen":{"title":"Spitse T-toppen","short":"Spitse T-toppen op het ECG zijn een vroeg teken van hyperkaliëmie.","definition":"<p>Bij <strong>hyperkaliëmie</strong> versnelt de repolarisatie, waardoor de T-top hoog, smal en symmetrisch wordt. Bij verder stijgend kalium volgen een verlengd PR-interval, afvlakken van de P-top, verbreding van het QRS-complex en uiteindelijk een sinusgolfpatroon en ventrikelfibrilleren. Ook in de vroege fase van een myocardinfarct kunnen hyperacute T-toppen voorkomen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"spitse t-toppen|hoge spitse t-toppen","option_only":true},"salbutamol vernevelen":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"salbutamol vernevelen|salbutamol verneveling|salbutamol|saba|kortwerkende luchtwegverwijder","option_only":true},"melatonine":{"title":"Melatonine","short":"Melatonine is een hormoon uit de pijnappelklier dat in het donker wordt afgegeven en het slaap-waakritme helpt regelen.","definition":"<p><strong>Melatonine</strong> wordt gemaakt uit serotonine en vooral ’s avonds en ’s nachts afgegeven; licht (via de retina en nucleus suprachiasmaticus) remt de afgifte. Als middel wordt het gebruikt bij een verschoven slaapritme, jetlag en bepaalde slaapproblemen bij kinderen en ouderen; als slaapmiddel is het effect bescheiden.</p>","image_url":"","wiki_title":"Melatonin","match":"melatonine|melatonin","option_only":true},"acetylcysteïne":{"title":"Acetylcysteïne","short":"Acetylcysteïne is het antidotum bij paracetamolvergiftiging; het vult het glutathion in de lever aan.","definition":"<p>Bij een <strong>paracetamolintoxicatie</strong> raakt glutathion uitgeput en hoopt de toxische metaboliet NAPQI zich op. Acetylcysteïne levert cysteïne voor nieuw glutathion en werkt het best binnen 8–10 uur na inname; de indicatie wordt bepaald met de paracetamolspiegel en het nomogram. Het wordt ook als slijmoplosser gebruikt.</p>","image_url":"","wiki_title":"Acetylcysteine","match":"acetylcysteïne|acetylcysteine|n-acetylcysteïne","option_only":true},"bopz":{"title":"Wet Bopz / Wet verplichte ggz","short":"De wet Bopz regelde gedwongen opname in de psychiatrie; sinds 2020 vervangen door de Wet verplichte ggz (Wvggz) en de Wet zorg en dwang.","definition":"<p>De <strong>Wet Bopz</strong> stond gedwongen opname alleen toe bij gevaar door een psychische stoornis. Sinds 2020 regelt de <strong>Wvggz</strong> verplichte zorg in de ggz (ook ambulant) en de Wet zorg en dwang (Wzd) onvrijwillige zorg bij dementie en verstandelijke beperking. Een crisismaatregel wordt door de burgemeester genomen; een zorgmachtiging door de rechter.</p>","image_url":"","wiki_title":"","match":"bopz|wet bopz|wvggz|wet verplichte ggz","option_only":true},"nucleair cataract":{"title":"Nucleaire cataract","short":"Bij nucleaire cataract vertroebelt en verkleurt de kern van de ooglens, vaak met een toenemende bijziendheid.","definition":"<p><strong>Nucleaire cataract</strong> is de meest voorkomende ouderdomsstaar. De lenskern wordt geler en harder; door de toegenomen brekingskracht kunnen mensen soms weer zonder leesbril lezen (‘second sight’). Kleuren worden minder helder waargenomen. Behandeling is een staaroperatie.</p>","image_url":"","wiki_title":"Cataract","match":"nucleair cataract|nucleaire cataract|kernstaar","option_only":true},"glaucoom":{"title":"Glaucoom","short":"Glaucoom is een groep oogziekten met schade aan de oogzenuw en gezichtsvelduitval, meestal samenhangend met een verhoogde oogdruk.","definition":"<p>Bij het meest voorkomende <strong>openkamerhoekglaucoom</strong> verloopt de schade langzaam en ongemerkt, met eerst uitval in het perifere gezichtsveld en een toenemende excavatie van de papil. Risicofactoren: hogere leeftijd, verhoogde oogdruk, familie, myopie en een donkere huidskleur. Behandeling met oogdrukverlagende druppels, laser of operatie. Acuut glaucoom is een apart, acuut ziektebeeld.</p>","image_url":"","wiki_title":"Glaucoma","match":"glaucoom|groene staar|openkamerhoekglaucoom","option_only":true},"nadroparine":{"title":"Nadroparine (LMWH)","short":"Nadroparine is een laagmoleculaire heparine die factor Xa remt via antitrombine; gebruikt ter preventie en behandeling van trombose.","definition":"<p><strong>LMWH's</strong> worden subcutaan toegediend, hebben een voorspelbare werking en hoeven meestal niet te worden gemonitord. Ze worden gebruikt bij trombose, ter tromboseprofylaxe (bijv. na operaties of bij immobilisatie) en in de zwangerschap. Ze worden via de nier geklaard; bij nierfalen is dosisaanpassing nodig. Bijwerkingen: bloedingen en (zeldzamer dan bij ongefractioneerde heparine) HIT.</p>","image_url":"","wiki_title":"Nadroparin","match":"nadroparine|laagmoleculaire gewichtsheparine|laagmoleculair heparine|lmwh|fraxiparine|dalteparine","option_only":true},"gliclazide":{"title":"Gliclazide","short":"Gliclazide is een sulfonylureumderivaat dat de insulineafgifte uit de bètacellen stimuleert; gebruikt bij diabetes type 2.","definition":"<p><strong>Gliclazide</strong> sluit ATP-gevoelige kaliumkanalen in de bètacel, waardoor insuline vrijkomt, ook bij een lage glucose. Het belangrijkste risico is hypoglykemie, vooral bij ouderen, bij overslaan van maaltijden en bij nierfunctiestoornissen. Het kan gewichtstoename geven.</p>","image_url":"","wiki_title":"Gliclazide","match":"gliclazide","option_only":true},"tamsulosine":{"title":"Tamsulosine","short":"Tamsulosine is een α1-blokker die de gladde spier van prostaat en blaashals ontspant en zo plasklachten bij BPH vermindert.","definition":"<p><strong>Tamsulosine</strong> is relatief selectief voor de α1A-receptoren in de prostaat en geeft daardoor minder bloeddrukdaling dan andere alfablokkers. Het wordt gebruikt bij mictieklachten door benigne prostaathyperplasie en soms om het passeren van een ureterkelsteen te bevorderen. Bijwerkingen: duizeligheid, orthostatische hypotensie, retrograde ejaculatie en het floppy-irissyndroom bij staaroperaties.</p>","image_url":"","wiki_title":"Tamsulosin","match":"tamsulosine|tamsulosin","option_only":true},"paroxetine":{"title":"Paroxetine","short":"Paroxetine is een SSRI met relatief veel anticholinerge bijwerkingen en ontwenningsverschijnselen bij stoppen.","definition":"<p><strong>Paroxetine</strong> remt de heropname van serotonine en wordt gebruikt bij depressie en angststoornissen. Het heeft een korte halfwaardetijd, waardoor abrupt stoppen vaak onttrekkingsverschijnselen geeft. Het is een sterke CYP2D6-remmer (interacties, o.a. met tamoxifen) en wordt in de zwangerschap liever vermeden.</p>","image_url":"","wiki_title":"Paroxetine","match":"paroxetine","option_only":true},"blaasretentie":{"title":"Urineretentie","short":"Bij urineretentie kan iemand de blaas niet (volledig) legen, acuut met pijnlijke volle blaas of chronisch met overloopincontinentie.","definition":"<p><strong>Urineretentie</strong> ontstaat door een obstructie (prostaatvergroting, urethrastrictuur, stolsels), medicatie (anticholinergica, opioïden), neurologische oorzaken (dwarslaesie, cauda-equinasyndroom, diabetische neuropathie) of na operaties en anesthesie. Acute retentie wordt behandeld met een katheter.</p>","image_url":"","wiki_title":"Urinary retention","match":"blaasretentie|urineretentie|retentieblaas","option_only":true},"wervelfractuur":{"title":"Wervelfractuur","short":"Een wervelfractuur is een breuk van een wervel; bij ouderen vaak een inzakking door osteoporose.","definition":"<p><strong>Osteoporotische wervelfracturen</strong> ontstaan vaak bij gering trauma of spontaan, vooral in de borst- en lendenwervelkolom, en geven acute rugpijn, lengteverlies en een toenemende kyfose. Na hoogenergetisch trauma kunnen wervelfracturen instabiel zijn en het ruggenmerg bedreigen. Een wervelinzakking bij een jonger persoon zonder trauma vraagt om onderzoek naar o.a. metastasen of myeloom.</p>","image_url":"","wiki_title":"Vertebral compression fracture","match":"wervelfractuur|wervelinzakking|inzakkingsfractuur","option_only":true},"artrose heup":{"title":"Coxartrose (heupartrose)","short":"Coxartrose is slijtage van het heupgewricht, met pijn in lies of bil en een beperkte (vooral endo)rotatie.","definition":"<p>Bij <strong>coxartrose</strong> geeft het kraakbeenverlies startpijn, pijn bij belasting en een beperking van de bewegingen, het eerst van endorotatie en flexie. De pijn wordt vaak in de lies gevoeld en kan uitstralen naar de knie. Behandeling begint met oefentherapie, gewichtsverlies en pijnstilling; bij ernstige klachten volgt een totale heupprothese.</p>","image_url":"","wiki_title":"Hip osteoarthritis","match":"artrose heup|coxartrose|heupartrose","option_only":true},"kaliumbeperkt dieet":{"title":"Kaliumbeperkt dieet","short":"Een kaliumbeperkt dieet beperkt kaliumrijk voedsel, bijvoorbeeld bij chronische nierschade met hyperkaliëmie.","definition":"<p>Kaliumrijke voedingsmiddelen zijn o.a. aardappelen, groenten, fruit (banaan, gedroogd fruit), noten en zoutvervangers. Bij gevorderde <strong>nierschade</strong> kan beperking nodig zijn; kalium kan ook worden verlaagd door aardappelen en groenten te koken in veel water (dubbel koken).</p>","image_url":"","wiki_title":"","match":"kaliumbeperkt dieet","option_only":true},"reflux oesophagitis":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"reflux oesophagitis","option_only":true},"een myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"een myocardinfarct","option_only":true},"doorgemaakt mi":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"doorgemaakt mi","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"een thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"een thiazidediureticum","option_only":true},"een statine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"een statine","option_only":true},"atorvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"atorvastatine","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"overdosering acenocoumarol":{"title":"Acenocoumarol","short":"Acenocoumarol is een kortwerkende cumarine (vitamine K-antagonist) voor antistolling, gedoseerd op geleide van de INR.","definition":"<p><strong>Acenocoumarol</strong> werkt net als fenprocoumon door remming van de vitamine K-cyclus, maar heeft een kortere halfwaardetijd. Het wordt gebruikt bij o.a. boezemfibrilleren, trombose en kunstkleppen. Controle via de INR is nodig; veel geneesmiddelen (zoals antibiotica) en wisselende vitamine K-inname beïnvloeden het effect.</p>","image_url":"","wiki_title":"Acenocoumarol","match":"overdosering acenocoumarol","option_only":true},"aspirine in een lage dosering":{"title":"Acetylsalicylzuur","short":"Acetylsalicylzuur (aspirine) remt onomkeerbaar het enzym cyclo-oxygenase; in lage dosis remt het de bloedplaatjesaggregatie.","definition":"<p><strong>Acetylsalicylzuur</strong> acetyleert en remt <em>onomkeerbaar</em> het enzym cyclo-oxygenase (COX-1 en COX-2). Daardoor worden minder prostaglandinen en tromboxaan A<sub>2</sub> gevormd.</p><p>In lage dosis (80–100 mg) remt het via tromboxaan de bloedplaatjesaggregatie voor de hele levensduur van het plaatje (±7–10 dagen); dit wordt gebruikt ter preventie van hart- en vaatziekten. In hoge dosis werkt het pijnstillend, koortsverlagend en ontstekingsremmend. Bijwerkingen: maagulcera, bloedingen en bij kinderen het syndroom van Reye.</p>","image_url":"","wiki_title":"Aspirin","match":"aspirine in een lage dosering","option_only":true},"ibuprofen":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"ibuprofen","option_only":true},"benzodiazepines":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"benzodiazepines","option_only":true},"oxycodon (een opiaat)":{"title":"Oxycodon","short":"Oxycodon is een sterk werkend opioïd voor (matig) ernstige pijn.","definition":"<p><strong>Oxycodon</strong> is een µ-opioïdreceptoragonist met een vergelijkbaar effect en bijwerkingenprofiel als morfine (obstipatie, sufheid, ademhalingsdepressie). Het wordt via de lever (CYP3A4, CYP2D6) omgezet en is daarom een alternatief bij nierfunctiestoornissen. Er zijn snel- en langwerkende vormen; misbruik is een probleem.</p>","image_url":"","wiki_title":"Oxycodone","match":"oxycodon (een opiaat)","option_only":true},"oxycodon (oxycontin/oxynorm)":{"title":"Oxycodon","short":"Oxycodon is een sterk werkend opioïd voor (matig) ernstige pijn.","definition":"<p><strong>Oxycodon</strong> is een µ-opioïdreceptoragonist met een vergelijkbaar effect en bijwerkingenprofiel als morfine (obstipatie, sufheid, ademhalingsdepressie). Het wordt via de lever (CYP3A4, CYP2D6) omgezet en is daarom een alternatief bij nierfunctiestoornissen. Er zijn snel- en langwerkende vormen; misbruik is een probleem.</p>","image_url":"","wiki_title":"Oxycodone","match":"oxycodon (oxycontin/oxynorm)","option_only":true},"refractie afwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractie afwijking","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"ergotherapeut":{"title":"Ergotherapeut","short":"Een ergotherapeut helpt mensen om dagelijkse activiteiten (zelfzorg, wonen, werk) weer zo zelfstandig mogelijk uit te voeren.","definition":"<p><strong>Ergotherapie</strong> richt zich op het handelen in het dagelijks leven, bijvoorbeeld met advies over hulpmiddelen, aanpassingen in huis en het aanleren van andere manieren van doen, o.a. bij reuma, CVA, dementie en na handletsel.</p>","image_url":"","wiki_title":"Occupational therapy","match":"ergotherapeut|ergotherapie","option_only":true},"een sglt2 remmer":{"title":"SGLT2-remmer","short":"SGLT2-remmers laten de nier glucose uitscheiden; ze verlagen de bloedglucose en beschermen hart en nieren.","definition":"<p><strong>SGLT2-remmers</strong> remmen de glucoseterugresorptie in de proximale tubulus. Naast glucoseverlaging (diabetes type 2) verminderen ze ziekenhuisopnames bij hartfalen en vertragen ze chronische nierschade. Bijwerkingen: genitale schimmelinfecties, volumedepletie en zeldzaam een euglykemische ketoacidose.</p>","image_url":"","wiki_title":"SGLT2 inhibitor","match":"een sglt2 remmer|sglt2-remmer|sglt2 remmer|empagliflozine|dapagliflozine","option_only":true},"ventriculaire extrasystolen":{"title":"Ventriculaire extrasystolen (VES)","short":"Ventriculaire extrasystolen zijn vroegtijdige hartslagen die uit de kamers ontstaan, met een breed QRS-complex.","definition":"<p>Losse <strong>VES</strong> komen bij veel gezonde mensen voor en worden gevoeld als een overgeslagen of harde slag. Uitlokkers zijn cafeïne, alcohol, stress en slaaptekort. Bij veel VES, klachten of onderliggende hartziekte is verder onderzoek nodig; zeer frequente VES kunnen de pompfunctie verminderen.</p>","image_url":"","wiki_title":"Premature ventricular contraction","match":"ventriculaire extrasystolen|ves|ventriculaire extrasystole","option_only":true},"spitse p-toppen":{"title":"P-pulmonale (spitse P-toppen)","short":"Hoge, spitse P-toppen (P-pulmonale) op het ECG wijzen op vergroting of overbelasting van het rechteratrium.","definition":"<p><strong>P-pulmonale</strong> (P-top ≥2,5 mm in II) komt voor bij pulmonale hypertensie, COPD, longembolie en tricuspidalisklepziekten. Een brede, tweetoppige P-top (P-mitrale) wijst juist op een linkeratriumvergroting.</p>","image_url":"","wiki_title":"P wave (electrocardiography)","match":"spitse p-toppen|p-pulmonale","option_only":true},"st-elevatie":{"title":"ST-elevatie","short":"ST-elevatie op het ECG wijst meestal op een acuut transmuraal myocardinfarct (STEMI), maar komt ook voor bij pericarditis en andere oorzaken.","definition":"<p>Bij een <strong>STEMI</strong> is de ST-elevatie beperkt tot een vaatgebied, vaak met spiegelbeeldige ST-depressie; snelle reperfusie (PCI) is nodig. Diffuse ST-elevatie met PR-depressie past bij pericarditis. Andere oorzaken: vroege repolarisatie, linkerventrikelhypertrofie, LBTB en het Brugada-syndroom.</p>","image_url":"","wiki_title":"ST elevation","match":"st-elevatie|stemi","option_only":true},"verbreed qrs-complex":{"title":"Breed QRS-complex","short":"Een breed QRS-complex (>120 ms) betekent een vertraagde depolarisatie van de kamers.","definition":"<p>Een <strong>breed QRS-complex</strong> komt voor bij een bundeltakblok, ventriculaire ritmes (ventrikeltachycardie), pre-excitatie (Wolff-Parkinson-White), pacemakerritme, ernstige hyperkaliëmie en intoxicaties met natriumkanaalblokkers (zoals tricyclische antidepressiva).</p>","image_url":"","wiki_title":"QRS complex","match":"verbreed qrs-complex","option_only":true},"overactieve blaas":{"title":"Overactieve blaas","short":"Bij een overactieve blaas is er een plotselinge, sterke aandrang tot plassen, vaak met frequent plassen en soms urine-incontinentie.","definition":"<p>De <strong>overactieve blaas</strong> komt veel voor bij ouderen. Behandeling bestaat uit blaastraining en bekkenbodemoefeningen, eventueel anticholinergica of een β3-agonist (mirabegron). Infectie, stenen en een blaastumor moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Overactive bladder","match":"overactieve blaas|urge-incontinentie|aandrangincontinentie","option_only":true},"ezetimib":{"title":"Ezetimib","short":"Ezetimib remt de opname van cholesterol in de dunne darm en verlaagt zo het LDL-cholesterol.","definition":"<p><strong>Ezetimib</strong> blokkeert het transporteiwit NPC1L1 in de darmwand. Het verlaagt het LDL met ongeveer 20% en wordt vaak met een statine gecombineerd. Het wordt goed verdragen.</p>","image_url":"","wiki_title":"Ezetimibe","match":"ezetimib|ezetimibe","option_only":true},"apixaban":{"title":"Apixaban (DOAC)","short":"Apixaban is een direct werkend oraal anticoagulans (DOAC) dat factor Xa remt.","definition":"<p><strong>DOAC's</strong> (factor Xa-remmers apixaban, rivaroxaban en edoxaban, en de trombineremmer dabigatran) worden gebruikt bij boezemfibrilleren en veneuze trombose. Ze hebben een snelle werking, weinig interacties en hoeven niet met INR te worden gecontroleerd. Bij kunstkleppen en ernstige nierfunctiestoornis zijn cumarines de keuze. Antidota: andexanet alfa (Xa-remmers) en idarucizumab (dabigatran).</p>","image_url":"","wiki_title":"Apixaban","match":"apixaban|rivaroxaban|edoxaban|doac|doac's|noac","option_only":true},"gebruik van dabigatran":{"title":"Dabigatran","short":"Dabigatran is een direct werkende trombineremmer (DOAC) die grotendeels via de nier wordt uitgescheiden.","definition":"<p><strong>Dabigatran</strong> wordt gebruikt bij boezemfibrilleren en veneuze trombose. Bij een verminderde nierfunctie hoopt het op, met risico op bloedingen. Het effect kan snel worden opgeheven met het antilichaamfragment idarucizumab.</p>","image_url":"","wiki_title":"Dabigatran","match":"gebruik van dabigatran|dabigatran|overdosering dabigatran","option_only":true},"carvedilol":{"title":"Carvedilol","short":"Carvedilol is een niet-selectieve bètablokker met ook α1-blokkerende werking, gebruikt bij hartfalen en hypertensie.","definition":"<p><strong>Carvedilol</strong> verlaagt hartfrequentie en afterload en vermindert de sterfte bij hartfalen met verminderde ejectiefractie. Het wordt ook gebruikt om de portale druk te verlagen bij levercirrose met varices. Door de β2-blokkade is het minder geschikt bij astma.</p>","image_url":"","wiki_title":"Carvedilol","match":"carvedilol","option_only":true},"atenolol":{"title":"Atenolol","short":"Atenolol is een cardioselectieve, hydrofiele bètablokker die via de nier wordt uitgescheiden.","definition":"<p><strong>Atenolol</strong> passeert de bloed-hersenbarrière nauwelijks (minder nachtmerries en vermoeidheid) en moet bij nierfunctiestoornissen in lagere dosis worden gegeven. Het wordt minder gebruikt dan metoprolol of bisoprolol.</p>","image_url":"","wiki_title":"Atenolol","match":"atenolol","option_only":true},"ziekte van meniere":{"title":"Ziekte van Ménière","short":"De ziekte van Ménière geeft aanvallen van draaiduizeligheid met oorsuizen, een vol gevoel in het oor en schommelend gehoorverlies.","definition":"<p>Bij <strong>Ménière</strong> is er waarschijnlijk een ophoping van endolymfe in het binnenoor (endolymfatische hydrops). Aanvallen duren 20 minuten tot uren. Het gehoorverlies is aanvankelijk laagfrequent en wisselend, later blijvend. In late stadia kunnen otolietcrises van Tumarkin optreden.</p>","image_url":"","wiki_title":"Ménière's disease","match":"ziekte van meniere|ziekte van ménière|ménière","option_only":true},"stabiele angina pectoris":{"title":"Stabiele angina pectoris","short":"Bij stabiele angina pectoris ontstaat bij inspanning een drukkende pijn op de borst door een vernauwde kransslagader, die in rust binnen minuten verdwijnt.","definition":"<p><strong>Angina pectoris</strong> ontstaat als het zuurstofaanbod tekortschiet bij een verhoogde vraag. Uitlokkers: inspanning, kou, emoties en maaltijden. Behandeling: nitroglycerine bij een aanval, bètablokkers of calciumantagonisten, acetylsalicylzuur en een statine; bij ernstige klachten een PCI of bypassoperatie. Bij pijn in rust of toenemende klachten spreekt men van instabiele angina.</p>","image_url":"","wiki_title":"Angina","match":"stabiele angina pectoris|angina pectoris","option_only":true},"hypomagnesiëmie":{"title":"Hypomagnesiëmie","short":"Hypomagnesiëmie is een te laag magnesium in het bloed, met spierkrampen, tetanie en hartritmestoornissen.","definition":"<p>Oorzaken zijn o.a. diarree, alcoholisme, diuretica, protonpompremmers en aminoglycosiden. Een laag magnesium houdt hypokaliëmie en hypocalciëmie in stand (minder PTH-afgifte), die pas corrigeren als het magnesium is aangevuld.</p>","image_url":"","wiki_title":"Hypomagnesemia","match":"hypomagnesiëmie|hypomagnesiemie","option_only":true},"hyperventilatie":{"title":"Hyperventilatie","short":"Bij hyperventilatie wordt meer geademd dan nodig is, waardoor het CO₂ daalt (respiratoire alkalose) met tintelingen en duizeligheid.","definition":"<p>Een <strong>hyperventilatieaanval</strong> kan worden uitgelokt door angst of paniek en geeft tintelingen rond de mond en in de vingers, duizeligheid, benauwdheid en soms carpopedale spasmen. Hyperventilatie kan ook compensatoir zijn (metabole acidose) of door hypoxie, pijn of koorts ontstaan; die oorzaken moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Hyperventilation","match":"hyperventilatie|chronisch hyperventileren","option_only":true},"antinucleaire factor (anf)":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"antinucleaire factor (anf)|ana|antinucleaire antistoffen","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"acuut myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"acuut myocardinfarct","option_only":true},"anf":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"anf","option_only":true},"st-elevaties":{"title":"ST-elevatie","short":"ST-elevatie op het ECG wijst meestal op een acuut transmuraal myocardinfarct (STEMI), maar komt ook voor bij pericarditis en andere oorzaken.","definition":"<p>Bij een <strong>STEMI</strong> is de ST-elevatie beperkt tot een vaatgebied, vaak met spiegelbeeldige ST-depressie; snelle reperfusie (PCI) is nodig. Diffuse ST-elevatie met PR-depressie past bij pericarditis. Andere oorzaken: vroege repolarisatie, linkerventrikelhypertrofie, LBTB en het Brugada-syndroom.</p>","image_url":"","wiki_title":"ST elevation","match":"st-elevaties","option_only":true},"monoamine-oxidase remmer (mao-remmer)":{"title":"Monoamineoxidase (MAO)","short":"Monoamineoxidase is een enzym in de buitenmembraan van mitochondriën dat monoamines zoals serotonine, noradrenaline en dopamine afbreekt.","definition":"<p>Er zijn twee vormen: <strong>MAO-A</strong> (vooral serotonine en noradrenaline, ook tyramine in de darm) en <strong>MAO-B</strong> (vooral dopamine). MAO-remmers worden gebruikt bij depressie (MAO-A) en de ziekte van Parkinson (MAO-B, bijv. selegiline, rasagiline). Bij niet-selectieve remmers kan tyraminerijk voedsel (oude kaas) een hypertensieve crisis geven.</p>","image_url":"","wiki_title":"Monoamine oxidase","match":"monoamine-oxidase remmer (mao-remmer)","option_only":true},"thiazide-diuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide-diuretica","option_only":true},"calciumantagonisten":{"title":"Amlodipine","short":"Amlodipine is een langwerkende dihydropyridine-calciumantagonist die de arteriën verwijdt; gebruikt bij hypertensie en angina.","definition":"<p><strong>Dihydropyridines</strong> (amlodipine, nifedipine) blokkeren L-type calciumkanalen vooral in vasculaire gladde spier en hebben weinig effect op het hart. Bijwerkingen zijn enkeloedeem (door precapillaire vaatverwijding), hoofdpijn, flushing en tandvleeshyperplasie. Non-dihydropyridines (verapamil, diltiazem) werken juist meer op hart en AV-knoop.</p>","image_url":"","wiki_title":"Amlodipine","match":"calciumantagonisten","option_only":true},"eeg":{"title":"EEG (elektro-encefalogram)","short":"Een EEG registreert de elektrische activiteit van de hersenen via elektroden op de hoofdhuid.","definition":"<p>Een <strong>EEG</strong> wordt vooral gebruikt bij epilepsie (epileptiforme afwijkingen, type epilepsie), bij onverklaarde bewustzijnsstoornissen (non-convulsieve status, encefalopathie) en bij slaaponderzoek. Een normaal EEG tussen aanvallen sluit epilepsie niet uit.</p>","image_url":"","wiki_title":"Electroencephalography","match":"eeg|elektro-encefalogram","option_only":true},"fysiotherapeut":{"title":"Fysiotherapeut","short":"Een fysiotherapeut behandelt klachten van het bewegingsapparaat en helpt mensen beter te bewegen, met oefentherapie, advies en manuele technieken.","definition":"<p><strong>Fysiotherapie</strong> wordt o.a. ingezet bij rug- en nekklachten, na operaties en blessures, bij artrose, COPD en na een beroerte. Het is direct toegankelijk, zonder verwijzing van de huisarts.</p>","image_url":"","wiki_title":"Physical therapy","match":"fysiotherapeut|fysiotherapie","option_only":true},"praktijkondersteuner ouderenzorg":{"title":"Praktijkondersteuner (POH)","short":"Een praktijkondersteuner ondersteunt de huisarts bij de zorg voor bijvoorbeeld chronisch zieken, kwetsbare ouderen en psychische klachten.","definition":"<p>Er zijn <strong>POH's</strong> voor somatiek (diabetes, astma/COPD, hart- en vaatziekten), GGZ en ouderenzorg. Ze voeren controles uit volgens protocollen en verwijzen zo nodig terug naar de huisarts.</p>","image_url":"","wiki_title":"","match":"praktijkondersteuner ouderenzorg|praktijkondersteuner|poh","option_only":true},"specialistisch verpleegkundige":{"title":"Verpleegkundig specialist","short":"Een verpleegkundig specialist is een verpleegkundige met een masteropleiding die zelfstandig bepaalde medische taken mag uitvoeren.","definition":"<p>Een <strong>verpleegkundig specialist</strong> mag binnen het eigen deskundigheidsgebied o.a. diagnosen stellen, behandelingen starten en geneesmiddelen voorschrijven. Ze werken vaak in de chronische zorg, oncologie en spoedzorg.</p>","image_url":"","wiki_title":"","match":"specialistisch verpleegkundige|verpleegkundig specialist","option_only":true},"anti-fosfolipase a2 receptor antistoffen":{"title":"Anti-PLA2R-antistoffen","short":"Anti-PLA2R-antistoffen zijn auto-antistoffen tegen een receptor op podocyten en de belangrijkste oorzaak van primaire membraneuze glomerulopathie.","definition":"<p>De hoogte van de <strong>anti-PLA2R</strong>-titer correleert met de ziekteactiviteit en kan worden gebruikt om de behandeling te volgen; bij een positieve test is een nierbiopt soms niet nodig.</p>","image_url":"","wiki_title":"","match":"anti-fosfolipase a2 receptor antistoffen|anti-pla2r","option_only":true},"stressincontinentie":{"title":"Stressincontinentie","short":"Bij stressincontinentie verliest iemand urine bij een drukverhoging in de buik, zoals hoesten, niezen of tillen.","definition":"<p><strong>Stressincontinentie</strong> komt vooral bij vrouwen voor, door een zwakke bekkenbodem of sfincter na bevallingen, overgewicht en ouderdom; bij mannen na een prostatectomie. Behandeling met bekkenfysiotherapie, eventueel een pessarium of een operatie (bandje).</p>","image_url":"","wiki_title":"Stress incontinence","match":"stressincontinentie|inspanningsincontinentie","option_only":true},"overloopincontinentie":{"title":"Overloopincontinentie","short":"Bij overloopincontinentie loopt urine ongewild weg doordat de blaas overvol is, door een obstructie of een slap werkende blaasspier.","definition":"<p>Oorzaken van <strong>overloopincontinentie</strong> zijn prostaatvergroting, urethrastrictuur, diabetische neuropathie, anticholinergica en neurologische aandoeningen. Na het plassen blijft er een groot residu achter (bladderscan). Behandeling van de oorzaak, soms katheteriseren.</p>","image_url":"","wiki_title":"Overflow incontinence","match":"overloopincontinentie","option_only":true},"metformine (biguanide)":{"title":"Metformine","short":"Metformine is het eerstekeusmiddel bij diabetes mellitus type 2; het remt vooral de glucoseproductie door de lever.","definition":"<p><strong>Metformine</strong> is een biguanide dat de <em>gluconeogenese in de lever</em> remt en de insulinegevoeligheid van spier verbetert. Het stimuleert de insulineafgifte niet en geeft daarom op zichzelf geen hypoglykemie.</p><p>Het is eerste keus bij diabetes type 2 en is gewichtsneutraal. Bijwerkingen zijn vooral maag-darmklachten; zeldzaam is lactaatacidose (risico bij ernstige nierfunctiestoornis). Langdurig gebruik kan vitamine B12-tekort geven.</p>","image_url":"","wiki_title":"Metformin","match":"metformine (biguanide)","option_only":true},"anti-dsdna":{"title":"Anti-dsDNA-antistoffen","short":"Anti-dsDNA-antistoffen zijn auto-antistoffen tegen dubbelstrengs DNA en zeer specifiek voor systemische lupus erythematodes (SLE).","definition":"<p>De titer van <strong>anti-dsDNA</strong> stijgt vaak bij ziekteactiviteit, vooral bij lupusnefritis, samen met een daling van complement (C3, C4). Een positieve ANA is gevoelig maar weinig specifiek; anti-dsDNA en anti-Sm zijn juist specifiek.</p>","image_url":"","wiki_title":"Anti-dsDNA antibodies","match":"anti-dsdna|anti-dubbelstrengs dna antistoffen|anti-dsdna-antistoffen","option_only":true},"anca":{"title":"ANCA","short":"ANCA zijn auto-antistoffen tegen eiwitten in neutrofielen (PR3, MPO) die horen bij kleinevatenvasculitis.","definition":"<p><strong>PR3-ANCA</strong> (c-ANCA) past vooral bij granulomatose met polyangiitis; <strong>MPO-ANCA</strong> (p-ANCA) bij microscopische polyangiitis en EGPA. ANCA-vasculitis kan snel progressieve glomerulonefritis en longbloedingen geven.</p>","image_url":"","wiki_title":"Anti-neutrophil cytoplasmic antibody","match":"anca|anca antistoffen|c-anca|p-anca|anti-pr3|anti-mpo","option_only":true},"wgbo":{"title":"WGBO (Wet op de geneeskundige behandelingsovereenkomst)","short":"De WGBO regelt de rechten en plichten van patiënt en hulpverlener bij een medische behandeling.","definition":"<p>Onder de <strong>WGBO</strong> vallen o.a. het recht op informatie, toestemming (informed consent), het medisch dossier (inzage, bewaartermijn) en het beroepsgeheim. Bij wilsonbekwame patiënten beslist een vertegenwoordiger. Voor kinderen gelden leeftijdsgrenzen (12 en 16 jaar).</p>","image_url":"","wiki_title":"","match":"wgbo|wet geneeskundige behandelovereenkomst|wet op de geneeskundige behandelingsovereenkomst","option_only":true},"anti-dubbelstrengs dna antistoffen":{"title":"Anti-dsDNA-antistoffen","short":"Anti-dsDNA-antistoffen zijn auto-antistoffen tegen dubbelstrengs DNA en zeer specifiek voor systemische lupus erythematodes (SLE).","definition":"<p>De titer van <strong>anti-dsDNA</strong> stijgt vaak bij ziekteactiviteit, vooral bij lupusnefritis, samen met een daling van complement (C3, C4). Een positieve ANA is gevoelig maar weinig specifiek; anti-dsDNA en anti-Sm zijn juist specifiek.</p>","image_url":"","wiki_title":"Anti-dsDNA antibodies","match":"anti-dubbelstrengs dna antistoffen","option_only":true},"anca antistoffen":{"title":"ANCA","short":"ANCA zijn auto-antistoffen tegen eiwitten in neutrofielen (PR3, MPO) die horen bij kleinevatenvasculitis.","definition":"<p><strong>PR3-ANCA</strong> (c-ANCA) past vooral bij granulomatose met polyangiitis; <strong>MPO-ANCA</strong> (p-ANCA) bij microscopische polyangiitis en EGPA. ANCA-vasculitis kan snel progressieve glomerulonefritis en longbloedingen geven.</p>","image_url":"","wiki_title":"Anti-neutrophil cytoplasmic antibody","match":"anca antistoffen","option_only":true},"gliclazide (su-derivaat)":{"title":"Gliclazide","short":"Gliclazide is een sulfonylureumderivaat dat de insulineafgifte uit de bètacellen stimuleert; gebruikt bij diabetes type 2.","definition":"<p><strong>Gliclazide</strong> sluit ATP-gevoelige kaliumkanalen in de bètacel, waardoor insuline vrijkomt, ook bij een lage glucose. Het belangrijkste risico is hypoglykemie, vooral bij ouderen, bij overslaan van maaltijden en bij nierfunctiestoornissen. Het kan gewichtstoename geven.</p>","image_url":"","wiki_title":"Gliclazide","match":"gliclazide (su-derivaat)","option_only":true},"angiotensine converting enzyme remmers (ace-remmers)":{"title":"ACE-remmers","short":"Bloeddrukverlagers die ook de intraglomerulaire druk verlagen en proteïnurie verminderen.","definition":"<p><b>ACE-remmers</b> remmen het angiotensine-converting enzyme, waardoor minder angiotensine II wordt gevormd. Ze geven vasodilatatie van vooral de efferente arteriole en verlagen de systemische bloeddruk; beide verlagen de intraglomerulaire druk, wat de proteïnurie vermindert en nefroprotectief werkt.</p>","image_url":"","wiki_title":"ACE inhibitor","match":"angiotensine converting enzyme remmers (ace-remmers)","option_only":true},"non-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID","short":"Non-steroidal anti-inflammatory drug (aspirine, ibuprofen); remt COX-enzymen en daarmee ontsteking en plaatjesaggregatie.","definition":"<p><b>NSAID's</b> remmen cyclo-oxygenase: ontstekingsremmend en pijnstillend, maar met bloedingsrisico en maagslijmvliesschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"non-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"jodium":{"title":"Jodium","short":"Sporenelement dat onmisbaar is voor de aanmaak van schildklierhormonen T3 en T4. Een tekort leidt tot struma (vergrote schildklier).","definition":"<p><b>Jodium</b> wordt door de schildklier opgenomen en ingebouwd in thyreoglobuline om T3 en T4 te vormen. Bij jodiumtekort daalt de schildklierhormoonproductie, stijgt TSH en groeit de schildklier compensatoir (struma).</p>","image_url":"","wiki_title":"Iodine","match":"jodium","option_only":true},"specifieke serotonineheropnameremmer (ssri)":{"title":"SSRI","short":"Selectieve serotonineheropnameremmer; antidepressivum dat ook een trombocytopathie kan veroorzaken.","definition":"<p>Een <b>SSRI</b> (selectieve serotonineheropnameremmer) is een veelgebruikt antidepressivum. SSRI’s remmen de heropname van serotonine, ook in de bloedplaatjes, waardoor een <b>trombocytopathie</b> ontstaat en het risico op maag-/bloedingscomplicaties toeneemt, zeker samen met NSAIDs.</p>","image_url":"","wiki_title":"Selective serotonin reuptake inhibitor","match":"specifieke serotonineheropnameremmer (ssri)","option_only":true},"lithium":{"title":"Lithium","short":"Stemmingsstabilisator bij bipolaire stoornis; kan als bijwerking nefrogene diabetes insipidus geven.","definition":"<p><b>Lithium</b> is een stemmingsstabilisator bij de bipolaire stoornis. Een belangrijke bijwerking is <b>nefrogene diabetes insipidus</b>: de nier reageert onvoldoende op ADH, met polyurie en polydipsie als gevolg.</p>","image_url":"","wiki_title":"Lithium (medication)","match":"lithium","option_only":true},"verhoogde oogboldruk (glaucoom)":{"title":"Glaucoom","short":"Beschadiging van de oogzenuw, vaak door verhoogde oogdruk, met blijvend gezichtsvelduitval.","definition":"<p>Glaucoom is een progressieve beschadiging van de nervus opticus, vaak samenhangend met een verhoogde oogboldruk. Het veroorzaakt onomkeerbare gezichtsvelduitval en kan onbehandeld tot blindheid leiden.</p>","image_url":"","wiki_title":"Glaucoma","match":"verhoogde oogboldruk (glaucoom)","option_only":true},"cataract":{"title":"Cataract","short":"Vertroebeling van de ooglens (staar), een behandelbare (reversibele) oorzaak van slechtziendheid.","definition":"<p>Cataract (staar) is een vertroebeling van de ooglens, waardoor het zicht geleidelijk verslechtert. Het is de meest voorkomende, maar goed behandelbare (reversibele) oorzaak van slechtziendheid; een staaroperatie herstelt het zicht.</p>","image_url":"","wiki_title":"Cataract","match":"cataract","option_only":true},"bumetanide":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"bumetanide","option_only":true},"thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediureticum","option_only":true},"anti-nucleaire factor":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"anti-nucleaire factor","option_only":true},"urineweg infectie":{"title":"Urineweginfectie","short":"Infectie van de urinewegen, meestal bacterieel; kan leucocyturie en een positieve nitriettest geven.","definition":"<p>Een <b>urineweginfectie</b> is meestal een bacteriële infectie van blaas of hogere urinewegen, gekenmerkt door leucocyturie, bacteriurie en vaak een positieve nitriettest.</p>","image_url":"","wiki_title":"Urinary tract infection","match":"urineweg infectie","option_only":true},"urine weg infectie":{"title":"Urineweginfectie","short":"Infectie van de urinewegen, meestal bacterieel; kan leucocyturie en een positieve nitriettest geven.","definition":"<p>Een <b>urineweginfectie</b> is meestal een bacteriële infectie van blaas of hogere urinewegen, gekenmerkt door leucocyturie, bacteriurie en vaak een positieve nitriettest.</p>","image_url":"","wiki_title":"Urinary tract infection","match":"urine weg infectie","option_only":true},"retinal":{"title":"Retinal (vitamine A)","short":"Retinal is de vorm van vitamine A die in het oog aan opsine bindt en zo het lichtgevoelige rodopsine vormt.","definition":"<p>Een tekort aan <strong>vitamine A</strong> geeft nachtblindheid, droge ogen (xeroftalmie) en een verhoogde kans op infecties. Vitamine A en zijn derivaten (isotretinoïne) zijn in hoge doses teratogeen.</p>","image_url":"","wiki_title":"Retinal","match":"retinal|retinol|vitamine a","option_only":true},"protonpompremmer":{"title":"Protonpompremmer (PPI)","short":"Protonpompremmers remmen de H⁺/K⁺-ATPase van de pariëtale cellen en zijn de krachtigste remmers van de maagzuurproductie.","definition":"<p><strong>PPI's</strong> worden gebruikt bij refluxziekte, ulcera, H. pylori-eradicatie, maagbescherming bij NSAID's en een bloedend ulcus (intraveneus). Langdurig gebruik hangt samen met hypomagnesiëmie, vitamine B12-tekort, fracturen en infecties (<em>C. difficile</em>).</p>","image_url":"","wiki_title":"Proton-pump inhibitor","match":"protonpompremmer|ppi|omeprazol|pantoprazol|esomeprazol","option_only":true},"delier":{"title":"Delier","short":"Een delier is een acute, wisselende stoornis van aandacht en bewustzijn, met verwardheid, door een lichamelijke oorzaak.","definition":"<p>Een <strong>delier</strong> komt veel voor bij ouderen in het ziekenhuis, na operaties en bij infecties, medicatie, onttrekking (alcohol) en metabole stoornissen. Er is een hypoactieve en een hyperactieve vorm. Behandeling: de oorzaak behandelen, oriëntatie bieden, en zo nodig haloperidol.</p>","image_url":"","wiki_title":"Delirium","match":"delier|een delier|delirium","option_only":true},"een delier":{"title":"Delier","short":"Een delier is een acute, wisselende stoornis van aandacht en bewustzijn, met verwardheid, door een lichamelijke oorzaak.","definition":"<p>Een <strong>delier</strong> komt veel voor bij ouderen in het ziekenhuis, na operaties en bij infecties, medicatie, onttrekking (alcohol) en metabole stoornissen. Er is een hypoactieve en een hyperactieve vorm. Behandeling: de oorzaak behandelen, oriëntatie bieden, en zo nodig haloperidol.</p>","image_url":"","wiki_title":"Delirium","match":"een delier","option_only":true}};
